// === Tab: mySketch ===
//Code by Aaron Reuland

let particles=[]

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	colorMode(HSB, 120)
	let hueSetter= random(120)
	let sider=0
	for(let y=0; y<=height; y+=5){
		let h= map(y, 0, height, (hueSetter-15)%120, (hueSetter+15)%120)
		particles.push(new particle(sider%2, y, h, width, 0, 0))
		sider++
	}


	for(let y=3; y<=height; y+=10){
		var h=(hueSetter+40)%120+ random(-5, 5)
		let wide=noise(y*0.5)*width/2.2

		particles.push(new particle(0, y, h, wide, 300, 0))
		particles.push(new particle(1, y, h, wide, 300, 0))	
		particles.push(new particle(0, y-4, h, wide*0.99, 300, 1))
		particles.push(new particle(1, y-4, h, wide*0.99, 300, 1))		
	}

}

function draw() {
for(let p of particles){
	p.move();
	p.show()
}
}


class particle{
	constructor(side, y, baseHue, length, delay, shadow){
		this.side=side
		if(this.side==0){
			this.start=createVector(0, y)
			this.pos=this.start
			this.end=createVector(length, y)
		} else {
			this.start=createVector(width, y)
			this.pos=this.start
			this.end=createVector(width-length, y)
		}
		this.base=baseHue
		this.length=length
		this.finish=0
		this.delay=delay
		this.between=0
		this.frames=width*0.75
		this.shadow=shadow
	}


	move(){
		if(this.delay>=0){
			this.delay--
		}

		if (this.between < this.frames && this.delay<=0) {
				let framesMap = map(this.between, 0, this.frames, 0, 1);
				this.pos = p5.Vector.lerp(this.start, this.end, easeOutSine(framesMap))

				this.between++
			}



		if(this.between>this.frames){
			  let index = particles.indexOf(this);
		particles.splice(index, 1);
		}
	}

	show(){
		let hue= this.base+ noise(this.pos.x, this.pos.y)*12

		let brightness= map(Math.abs(this.pos.x - width/2), width/2, 0, 0, 120)
		if(this.shadow==1){
			brightness*=0.66
		}
		let sat= noise(this.pos.x/200, this.pos.y/200)*120
		fill(hue, sat, brightness)
		noStroke()
		rect(this.pos.x, this.pos.y, 5)
	}
}


function easeInOutSine(x){
return -(Math.cos(Math.PI * x) -1) / 2;

}

function easeOutSine(x){
  return Math.sin((x * Math.PI) / 2);

}

